\label{def:resnet}
Let \((H,\|\cdot\|_H)\) and \((P,\|\cdot\|_P)\) be normed vector spaces. Let \(x\in H\) be the input. Define \(y_0 = x\) and for \(k=1,\ldots,K\),
\begin{align*}
y_k = y_{k-1} + \alpha f_{W_k}(y_{k-1}),
\end{align*}
where \(f_{W_k}:H\to H\) is a twice continuously differentiable residual function parameterized by \(W_k\in P\). In this paper, we set the scaling factor as
\begin{align*}
\alpha = \frac{\beta}{K}, \qquad \beta = \Theta(1).
\end{align*}
The network output is \(y_K\in H\), and the loss is
\begin{align*}
\mathcal{L}(W) = l(y_K),
\end{align*}
with \(l:H\to\mathbb{R}\). The parameter tuple is \(W=(W_1,\ldots,W_K)\), and the perturbation directions are \(\Delta U=(\Delta U_1,\ldots,\Delta U_K)\) and \(\Delta V=(\Delta V_1,\ldots,\Delta V_K)\), with \(\Delta U_k,\Delta V_k\in P\).

\label{as1}
\begin{align*}
    \left\|x\right\|_H\le C_x,\qquad
    \left\|\Delta U_k\right\|_P\le 1,\qquad
    \left\|\Delta V_k\right\|_P\le 1.
\end{align*}

\label{as2}
There exist positive constants \(C_f\), \(L_f\), \(M_f\),
\(C_W\), \(M_{Wf}\), and \(M_{WW}\), independent of \(K\),
such that the following bounds hold for every \(k=1,\ldots,K\),
every \(y,y_1,y_2\in H\), every \(W_k,W_k'\in P\),
and every \(\Delta U_k,\Delta V_k\in P\). In appendix B.1 and B.2, with mild assumptions on parameter space and function regularity, we can satisfy our abstract residual function regularity for MLP and Attention blocks
\begin{itemize}
    \item[2.1]\textbf{First Order Regularity in Hidden State}
    \begin{align*}
        \left\|f_{W_k}(y_1)-f_{W_k}(y_2)\right\|_H \le L_f \left\|y_1-y_2\right\|_H
    \end{align*}
    \item[2.2]\textbf{Second Order Regularity in the Hidden State}
    \begin{align*}
        \left\|\partial_y f_{W_k}(y_1)-\partial_y f_{W_k}(y_2)\right\|_{H\to H} \le M_f \left\|y_1-y_2\right\|_H
    \end{align*}
    \item[2.3] \textbf{First Order Regularity in the Parameters}
    \begin{align*}
        \left\|f_{W_k}(y)-f_{W_k'}(y)\right\|_H \le C_W \left\|W_k-W_k'\right\|_P
    \end{align*}
    \item[2.4] \textbf{Mixed-State Parameter Regularity}
    \begin{align*}
        \left\|\partial_y f_{W_k}(y)-\partial_y f_{W_k'}(y)\right\|_{H\to H} \le M_{Wf} \left\|W_k-W_k'\right\|_P
    \end{align*}
    \item[2.5] \textbf{Second Order Regularity in the Parameters}
    \begin{align*}
        \left\|\partial_{W_k}f_{W_k}(y)[\Delta U_k]-\partial_{W_k'}f_{W_k'}(y)[\Delta U_k]\right\|_H \le M_{WW} \left\|W_k-W_k'\right\|_P \left\|\Delta U_k\right\|_P
    \end{align*}
    \item[2.6] \textbf{Bounded Output at Initial State}
    \begin{align*}
        \left\|f_{W_k}(y_0)\right\|_H \le C_f
    \end{align*}
\end{itemize}

\label{as3}
There exist constants \(L_J,M_J>0\), independent of \(K\), such that for all \(z\in H\),
\begin{align*}
\left\|\nabla l(z)\right\|_{H^*} \le L_J, \qquad
|\nabla^2 l(z)[u,v]| \le M_J \left\|u\right\|_H \left\|v\right\|_H.
\end{align*}

\label{thm:lipschitz}
Under \cref{as1,as2,as3} and \(\alpha=\beta/K\), \(\beta=\Theta(1)\), there exists \(L_{\mathrm{Lip}}=O(1)\), independent of \(K\), such that
\begin{align*}
\sup_{\|\Delta U\|_{\mathrm{block}}\le 1} |\nabla \mathcal{L}(W)[\Delta U]| \le L_{\mathrm{Lip}}.
\end{align*}
Consequently,
\begin{align*}
|\mathcal{L}(W^1)-\mathcal{L}(W^2)| \le L_{\mathrm{Lip}} \|W^1-W^2\|_{\mathrm{block}}.
\end{align*}

\label{thm:smooth}
Under \cref{as1,as2,as3} and \(\alpha=\beta/K\), \(\beta=\Theta(1)\), there exists \(L=O(1)\), independent of \(K\), such that
\begin{align*}
\sup_{\|\Delta U\|_{\mathrm{block}}\le 1, \|\Delta V\|_{\mathrm{block}}\le 1} |\nabla^2 \mathcal{L}(W)[\Delta U,\Delta V]| \le L.
\end{align*}
Consequently,
\begin{align*}
\|\nabla \mathcal{L}(W^1)-\nabla \mathcal{L}(W^2)\|_{\mathrm{block},*} \le L \|W^1-W^2\|_{\mathrm{block}}.
\end{align*}

\label{cor:fwd}
For all \(k=0,\ldots,K\),
\begin{align*}
\left\|y_k\right\|_H \le C_y := e^{\beta L_f} \Bigl( C_x + \frac{L_f C_x + C_f}{L_f} \Bigr).
\end{align*}

By \cref{as1} and \cref{as2},
\begin{align*}
\left\|f_{W_k}(y_{k-1})\right\|_H
&\le \left\|f_{W_k}(y_{k-1})-f_{W_k}(y_0)\right\|_H + \left\|f_{W_k}(y_0)\right\|_H
\le L_f \left\|y_{k-1}-y_0\right\|_H + C_f \\
&\le L_f \left\|y_{k-1}\right\|_H + L_f C_x + C_f.
\end{align*}
Let \(u_k := \left\|y_k\right\|_H\). Then
\begin{align*}
u_k \le (1+\alpha L_f) u_{k-1} + \alpha (L_f C_x + C_f).
\end{align*}
Unrolling,
\begin{align*}
u_k \le (1+\alpha L_f)^k u_0 + \alpha (L_f C_x + C_f) \sum_{i=0}^{k-1} (1+\alpha L_f)^i.
\end{align*}
Since \(u_0 \le C_x\) and \((1+\alpha L_f)^k \le e^{\beta L_f}\),
\begin{align*}
u_k \le e^{\beta L_f} \Bigl( C_x + \frac{L_f C_x + C_f}{L_f} \Bigr).
\end{align*}

\label{cor:jac}
For all \(k=1,\ldots,K\), with \(J_k := I + \alpha \partial_y f_{W_k}(y_{k-1})\),
\begin{align*}
\left\|J_k\right\|_{H\to H} \le 1+\alpha L_f.
\end{align*}

By \cref{as2} and the mean value theorem,
\begin{align*}
\left\|\partial_y f_{W_k}(y_{k-1})\right\|_{H\to H} \le L_f.
\end{align*}
Hence
\begin{align*}
\left\|J_k\right\|_{H\to H} \le \left\|I\right\|_{H\to H} + \alpha \left\|\partial_y f_{W_k}(y_{k-1})\right\|_{H\to H} \le 1+\alpha L_f.
\end{align*}

\label{cor:jacprod}
For all \(1\le j\le k\le K\),
\begin{align*}
\Bigl\| J_k J_{k-1} \cdots J_j \Bigr\|_{H\to H} \le (1+\alpha L_f)^{k-j+1} \le e^{\beta L_f} =: C_J.
\end{align*}

By \cref{cor:jac},
\begin{align*}
\Bigl\| J_k J_{k-1} \cdots J_j \Bigr\|_{H\to H} \le \prod_{i=j}^{k} \left\|J_i\right\|_{H\to H} \le (1+\alpha L_f)^{k-j+1}.
\end{align*}
Substituting \(\alpha = \beta/K\) and using \((1+x/K)^K \le e^x\) for \(x\ge 0\),
\begin{align*}
(1+\alpha L_f)^{k-j+1} \le (1+\beta L_f/K)^K \le e^{\beta L_f}.
\end{align*}

\label{cor:deriv}
Under \cref{as2}, the following bounds hold for all \(k=1,\ldots,K\) and all \(y\in H\):
\begin{align}
&\left\|\partial_y f_{W_k}(y)\right\|_{H\to H} \le L_f, \label{eq:bound1}\\
&\left\|\partial_y^2 f_{W_k}(y)[u,v]\right\|_H \le M_f \left\|u\right\|_H \left\|v\right\|_H, \label{eq:bound2}\\
&\left\|\partial_{W_k} f_{W_k}(y)\right\|_{P\to H} \le C_W, \label{eq:bound3}\\
&\left\|\partial_y \partial_{W_k} f_{W_k}(y)[h,w]\right\|_H \le M_{Wf} \left\|h\right\|_H \left\|w\right\|_P, \label{eq:bound4}\\
&\left\|\partial_{W_k}^2 f_{W_k}(y)[u,w]\right\|_H \le M_{WW} \left\|u\right\|_P \left\|w\right\|_P. \label{eq:bound5}
\end{align}

We prove equation~\ref{eq:bound1} in detail; the remaining bounds follow by the same argument applied to the corresponding Lipschitz condition in \cref{as2}.

By \cref{as2}, \(f_{W_k}\) is \(L_f\)-Lipschitz in \(y\):
\begin{align*}
\left\|f_{W_k}(y_1)-f_{W_k}(y_2)\right\|_H \le L_f \left\|y_1-y_2\right\|_H, \qquad \forall y_1,y_2\in H.
\end{align*}
Fix \(y\in H\) and \(h\in H\). For any \(t>0\), set \(y_1 = y+th\) and \(y_2 = y\). Then
\begin{align*}
\left\|f_{W_k}(y+th)-f_{W_k}(y)\right\|_H \le L_f \left\|th\right\|_H = L_f \, t \, \left\|h\right\|_H.
\end{align*}
Dividing by \(t\) gives
\begin{align*}
\left\|\frac{f_{W_k}(y+th)-f_{W_k}(y)}{t}\right\|_H \le L_f \left\|h\right\|_H.
\end{align*}
Taking the limit as \(t\to 0\) and using the definition of the directional derivative,
\begin{align*}
\left\|\partial_y f_{W_k}(y)[h]\right\|_H \le L_f \left\|h\right\|_H.
\end{align*}
Taking the supremum over all \(h\in H\) with \(\left\|h\right\|_H\le 1\),
\begin{align*}
\left\|\partial_y f_{W_k}(y)\right\|_{H\to H}
= \sup_{\left\|h\right\|_H\le 1} \left\|\partial_y f_{W_k}(y)[h]\right\|_H
\le L_f.
\end{align*}
This proves equation~\ref{eq:bound1}.

For equation~\ref{eq:bound2}, apply the same argument to the \(M_f\)-Lipschitz condition on \(\partial_y f_{W_k}\). For equation~\ref{eq:bound3}, use the \(C_W\)-Lipschitz condition on \(f_{W_k}\) in \(W_k\). For equation~\ref{eq:bound4}, use the \(M_{Wf}\)-Lipschitz condition on \(\partial_y f_{W_k}\) in \(W_k\). For equation~\ref{eq:bound5}, use the \(M_{WW}\)-Lipschitz condition on \(\partial_{W_k} f_{W_k}[\Delta U_k]\) in \(W_k\).

\label{def:directional}
For \(k=0,\ldots,K\) and \(j,\ell=1,\ldots,K\), define
\begin{align*}
s_k^{(j,U_j)} := \nabla_{W_j} y_k [\Delta U_j] \in H,
\end{align*}
\begin{align*}
h_k^{(j,\ell;U_j,V_\ell)} := \nabla^2_{W_j,W_\ell} y_k [\Delta U_j,\Delta V_\ell] \in H.
\end{align*}

Differentiating \(y_k = y_{k-1} + \alpha f_{W_k}(y_{k-1})\) with respect to \(W_j\) in direction \(\Delta U_j\),
\begin{align*}
s_k^{(j,U_j)} =
\begin{cases}
J_k s_{k-1}^{(j,U_j)}, & j<k,\\
\alpha \partial_{W_k} f_{W_k}(y_{k-1})[\Delta U_k], & j=k,\\
0, & j>k.
\end{cases}
\end{align*}
Since \(s_0^{(j,U_j)}=0\), we have \(s_j^{(j,U_j)} = \alpha \partial_{W_j} f_{W_j}(y_{j-1})[\Delta U_j]\), and iterating,
\begin{align*}
s_K^{(j,U_j)} = J_K J_{K-1} \cdots J_{j+1} \, \alpha \partial_{W_j} f_{W_j}(y_{j-1})[\Delta U_j].
\end{align*}
By \cref{cor:deriv} (see equation~\ref{eq:bound3}),
\begin{align*}
\left\|\partial_{W_j} f_{W_j}(y_{j-1})[\Delta U_j]\right\|_H \le C_W \left\|\Delta U_j\right\|_P \le C_W.
\end{align*}
By \cref{cor:jacprod},
\begin{align*}
\left\|s_K^{(j,U_j)}\right\|_H \le C_J \alpha C_W = \frac{C_s}{K}.
\end{align*}
Summing over \(j\),
\begin{align*}
\Bigl\| \sum_{j=1}^{K} s_K^{(j,U_j)} \Bigr\|_H \le \sum_{j=1}^{K} \left\|s_K^{(j,U_j)}\right\|_H \le K \cdot \frac{C_s}{K} = C_s.
\end{align*}

\label{cor:s-general}
From the proof above, it follows immediately that for all \(1\le j\le k\le K\),
\begin{align*}
\left\|s_k^{(j,U_j)}\right\|_H \le \frac{C_s}{K}, \qquad C_s := C_J \beta C_W.
\end{align*}
In particular, for \(k=K\),
\begin{align*}
\left\|s_K^{(j,U_j)}\right\|_H \le \frac{C_s}{K}, \qquad
\Bigl\| \sum_{j=1}^{K} s_K^{(j,U_j)} \Bigr\|_H \le C_s.
\end{align*}

\label{lem:lipschitz}
Let \(f:\mathbb{R}^{m\times n}\to\mathbb{R}\) be differentiable and \(\|\cdot\|_B\) be any matrix norm. If for all \(Z\) on the segment between \(Z^1,Z^2\) and all \(\|\Delta U\|_B\le 1\), \(|\nabla f(Z)[\Delta U]|\le L\), then
\begin{align*}
|f(Z^1)-f(Z^2)| \le L \|Z^1-Z^2\|_B.
\end{align*}

If \(Z^1=Z^2\), the claim is trivial. Assume \(Z^1\neq Z^2\). Let \(Z(t)=Z^2+(Z^1-Z^2)t\) for \(t\in[0,1]\). By the fundamental theorem of calculus,
\begin{align*}
f(Z^1)-f(Z^2) = \int_0^1 \nabla f(Z(t))[Z^1-Z^2] \, dt.
\end{align*}
Set \(\Delta U = (Z^1-Z^2)/\|Z^1-Z^2\|_B\). Then \(\|\Delta U\|_B=1\), and
\begin{align*}
|\nabla f(Z(t))[Z^1-Z^2]| = \|Z^1-Z^2\|_B \, |\nabla f(Z(t))[\Delta U]| \le L \|Z^1-Z^2\|_B.
\end{align*}
Integrating yields the result.

\label{lem:smooth}
Let \(f:\mathbb{R}^{m\times n}\to\mathbb{R}\) be twice differentiable and \(\|\cdot\|_B\) be any matrix norm. If for all \(Z\) on the segment between \(Z^1,Z^2\) and all \(\|\Delta U\|_B,\|\Delta V\|_B\le 1\), \(|\nabla^2 f(Z)[\Delta U,\Delta V]|\le L\), then
\begin{align*}
\|\nabla f(Z^1)-\nabla f(Z^2)\|_{B,*} \le L \|Z^1-Z^2\|_B.
\end{align*}

If \(Z^1=Z^2\), the claim is trivial. Assume \(Z^1\neq Z^2\). For any direction \(\Delta U\),
\begin{align*}
\nabla f(Z^1)[\Delta U] - \nabla f(Z^2)[\Delta U] = \int_0^1 \nabla^2 f(Z(t))[\Delta U, Z^1-Z^2] \, dt.
\end{align*}
By the definition of the dual norm,
\begin{align*}
\|\nabla f(Z^1)-\nabla f(Z^2)\|_{B,*} = \sup_{\|\Delta U\|_B\le 1} |\nabla f(Z^1)[\Delta U] - \nabla f(Z^2)[\Delta U]|.
\end{align*}
Set \(\Delta V = (Z^1-Z^2)/\|Z^1-Z^2\|_B\). Then \(\|\Delta V\|_B=1\), and
\begin{align*}
|\nabla^2 f(Z(t))[\Delta U, Z^1-Z^2]| = \|Z^1-Z^2\|_B \, |\nabla^2 f(Z(t))[\Delta U, \Delta V]| \le L \|Z^1-Z^2\|_B.
\end{align*}
Integrating and taking the supremum yields the result.

Under \cref{as1,as2,as3} and \(\alpha=\beta/K\), \(\beta=\Theta(1)\), there exists \(L_{\mathrm{Lip}}=O(1)\), independent of \(K\), such that
\begin{align*}
\sup_{\|\Delta U\|_{\mathrm{block}}\le 1} |\nabla \mathcal{L}(W)[\Delta U]| \le L_{\mathrm{Lip}}.
\end{align*}
Consequently,
\begin{align*}
|\mathcal{L}(W^1)-\mathcal{L}(W^2)| \le L_{\mathrm{Lip}} \|W^1-W^2\|_{\mathrm{block}}.
\end{align*}

By the chain rule,
\begin{align*}
\nabla_W \mathcal{L}(W)[\Delta U] = l'(y_K) \sum_{j=1}^{K} s_K^{(j,U_j)}.
\end{align*}
By \cref{as3} and \cref{cor:s-general},
\begin{align*}
|\nabla_W \mathcal{L}(W)[\Delta U]| \le L_J C_s =: L_{\mathrm{Lip}}.
\end{align*}
\Cref{lem:lipschitz} gives the Lipschitz consequence.

Under \cref{as1,as2,as3} and \(\alpha=\beta/K\), \(\beta=\Theta(1)\), there exists \(L=O(1)\), independent of \(K\), such that
\begin{align*}
\sup_{\|\Delta U\|_{\mathrm{block}}\le 1, \|\Delta V\|_{\mathrm{block}}\le 1} |\nabla^2 \mathcal{L}(W)[\Delta U,\Delta V]| \le L.
\end{align*}
Consequently,
\begin{align*}
\|\nabla \mathcal{L}(W^1)-\nabla \mathcal{L}(W^2)\|_{\mathrm{block},*} \le L \|W^1-W^2\|_{\mathrm{block}}.
\end{align*}

By the chain rule,
\begin{align*}
\nabla_W^2 \mathcal{L}[\Delta U,\Delta V]
= l''(y_K) \Bigl( \sum_{j=1}^{K} s_K^{(j,U_j)} \Bigr) \Bigl( \sum_{\ell=1}^{K} s_K^{(\ell,V_\ell)} \Bigr)
+ l'(y_K) \sum_{j=1}^{K} \sum_{\ell=1}^{K} h_K^{(j,\ell;U_j,V_\ell)}.
\end{align*}
By \cref{as3}, \cref{cor:s-general}, and equation~\ref{eq:second-order-sum},
\begin{align*}
|\nabla_W^2 \mathcal{L}[\Delta U,\Delta V]| \le M_J C_s^2 + L_J C_h =: L.
\end{align*}
\Cref{lem:smooth} gives the smoothness consequence.

\emph{Forward pass.} Introduce the pre-activations $z^{(\ell)}$ and activations $a^{(\ell)}$ by
\begin{align*}
a^{(0)}=y,\qquad
z^{(\ell)}=W^{(\ell)}a^{(\ell-1)}+b^{(\ell)},\qquad
a^{(\ell)}=\sigma(z^{(\ell)}),\qquad f_{W_k}(y)=a^{(N)}.
\end{align*}
By mean-normalization we have that $\|W\|_{H\rightarrow H} \leq \|W\|_{(p,mean)\rightarrow(q,mean)}\leq B_W$.Write $D^{(\ell)}:=\mathrm{Diag}(\sigma'(z^{(\ell)}))$ and $G^{(\ell)}:=D^{(\ell)}W^{(\ell)}$ for
the per-layer Jacobian, so that
\begin{align*}
\left\|D^{(\ell)}\right\|_{H\to H}\le L_\sigma,\qquad \left\|G^{(\ell)}\right\|_{H\to H}\le L_\sigma B_W
\end{align*}
hold globally (for all $y$). Let $F^{(\ell)}:=G^{(N)}G^{(N-1)}\cdots G^{(\ell+1)}$ denote forward
propagation from layer $\ell$ to the output (with $F^{(N)}=I$), so that
\begin{align*}
\left\|F^{(\ell)}\right\|_{H\to H}\le (L_\sigma B_W)^{N-\ell}.
\end{align*}

\emph{Bounded activations.} By the mean value theorem applied componentwise to
$a^{(\ell)}=\sigma(z^{(\ell)})$, there exists a diagonal matrix
$\tilde{D}^{(\ell)}=\mathrm{Diag}(\sigma'(\xi_1),\ldots,\sigma'(\xi_d))$ with
$\left\|\tilde{D}^{(\ell)}\right\|_{H\to H}\le L_\sigma$ such that
$a^{(\ell)}=\sigma(0)\mathbf{1}+\tilde{D}^{(\ell)}z^{(\ell)}$. Since $\left\|\mathbf{1}\right\|_H=1$, the
triangle inequality gives
\begin{align*}
\left\|a^{(\ell)}\right\|_H \le |\sigma(0)| + L_\sigma\left\|z^{(\ell)}\right\|_H.
\end{align*}
Combining this with $\left\|z^{(\ell)}\right\|_H\le B_W\left\|a^{(\ell-1)}\right\|_H+B_b$ and
$\left\|a^{(0)}\right\|_H=\left\|y\right\|_H\le C_y$, an induction over the $N=O(1)$ layers yields a constant
$R=R(N,L_\sigma,B_W,B_b,C_y)\ge1$ such that
\begin{align*}
\left\|a^{(\ell)}\right\|_H&\le R,\qquad \ell=0,\ldots,N,\\
\left\|z^{(\ell)}\right\|_H&\le R,\qquad \ell=1,\ldots,N,
\qquad\text{on } \{\left\|y\right\|_H\le C_y\}.
\end{align*}

\emph{(i) Global $y$-regularity.} The chain rule gives
\begin{align*}
\partial_y f_{W_k}(y) = G^{(N)}G^{(N-1)}\cdots G^{(1)},
\end{align*}
hence
\begin{align*}
\left\|\partial_y f_{W_k}(y)\right\|_{H\to H} \le (L_\sigma B_W)^N =: L_f
\qquad\text{for all } y\in H,
\end{align*}
which is equation~\ref{eq:bound1}; the $L_f$-Lipschitz condition in $y$ follows by the mean value theorem.

For the second derivative bound, expand the difference of the Jacobian products
as a telescoping sum: for $y_1,y_2\in H$,
\begin{align*}
\partial_y f(y_1)-\partial_y f(y_2)
= \sum_{\ell=1}^{N} G^{(N)}(y_1)\cdots G^{(\ell+1)}(y_1)\,
  \bigl[G^{(\ell)}(y_1)-G^{(\ell)}(y_2)\bigr]\,
  G^{(\ell-1)}(y_2)\cdots G^{(1)}(y_2).
\end{align*}
Since $G^{(\ell)}=D^{(\ell)}W^{(\ell)}$ and $\partial_y z^{(\ell)}=W^{(\ell)}G^{(\ell-1)}\cdots G^{(1)}$,
each factor is Lipschitz in $y$:
\begin{align*}
\left\|G^{(\ell)}(y_1)-G^{(\ell)}(y_2)\right\|_{H\to H}
&\le \left\|D^{(\ell)}(y_1)-D^{(\ell)}(y_2)\right\|_{H\to H}\,\left\|W^{(\ell)}\right\|_{H\to H}\\
&\le M_\sigma\,\left\|z^{(\ell)}(y_1)-z^{(\ell)}(y_2)\right\|_H\,B_W\\
&\le M_\sigma B_W^2(L_\sigma B_W)^{\ell-1}\left\|y_1-y_2\right\|_H.
\end{align*}
Substituting into the Leibniz sum (each term carries $N-1$ remaining factors of norm at most
$L_\sigma B_W$) yields $\left\|\partial_y f(y_1)-\partial_y f(y_2)\right\|_{H\to H}\le M_f\left\|y_1-y_2\right\|_H$ with
\begin{align*}
M_f := M_\sigma B_W^2 \sum_{\ell=1}^{N}(L_\sigma B_W)^{N+\ell-2},
\end{align*}
a constant independent of $K$; equivalently equation~\ref{eq:bound2} holds. This verifies the two global
$y$-conditions of \cref{as2}.

\emph{(ii) Localized $W$-regularity on the ball $\{\left\|y\right\|_H\le C_y\}$.} Differentiating through
layer $\ell$, the derivative with respect to the weight and bias blocks is
\begin{align*}
\partial_{W^{(\ell)}}f_{W_k}(y)[\Delta W^{(\ell)}]
  &= F^{(\ell)} D^{(\ell)}\,\Delta W^{(\ell)} a^{(\ell-1)},\\
\partial_{b^{(\ell)}}f_{W_k}(y)[\Delta b^{(\ell)}]
  &= F^{(\ell)} D^{(\ell)}\,\Delta b^{(\ell)}.
\end{align*}
Using $\left\|F^{(\ell)}\right\|_{H\to H}\le (L_\sigma B_W)^{N-\ell}$, $\left\|D^{(\ell)}\right\|_{H\to H}\le L_\sigma$,
$\left\|a^{(\ell-1)}\right\|_H\le R$, and $\left\|\Delta W_k\right\|_P\le 1$ (so each block has norm at most $1$),
we get
\begin{align*}
\left\|\partial_{W_k}f_{W_k}(y)\right\|_{P\to H}
\le \sum_{\ell=1}^{N}(L_\sigma B_W)^{N-\ell}L_\sigma(R+1) =: C_W,
\end{align*}
which is equation~\ref{eq:bound3}; the mean value theorem over the convex parameter set
$\Omega$ gives the $C_W$-Lipschitz condition in $W$.

For equation~\ref{eq:bound4}, differentiate $\partial_y f=G^{(N)}\cdots G^{(1)}$ with respect to
$W^{(\ell)}$ (for $m\ge\ell$, $G^{(m)}$ depends on $W^{(\ell)}$ through $z^{(m)}$; $G^{(\ell)}$
depends additionally on $W^{(\ell)}$ directly):
\begin{align*}
\partial_{W^{(\ell)}}\partial_y f\,[\Delta W^{(\ell)}]
= \sum_{m=\ell}^{N} G^{(N)}\cdots G^{(m+1)}\,
  \partial_{W^{(\ell)}}G^{(m)}[\Delta W^{(\ell)}]\,
  G^{(m-1)}\cdots G^{(1)}.
\end{align*}
We bound the differentiated factor on the ball, taking
$\|\Delta W^{(\ell)}\|_{(p,\mathrm{mean})\to(q,\mathrm{mean})}\le1$.
For $m=\ell$, differentiating
$G^{(\ell)}=D^{(\ell)}W^{(\ell)}$ gives
\begin{align*}
\left\|\partial_{W^{(\ell)}}G^{(\ell)}[\Delta W^{(\ell)}]\right\|_{H\to H}
&\le \left\|\partial_{W^{(\ell)}}D^{(\ell)}[\Delta W^{(\ell)}]\right\|_{H\to H}\,\left\|W^{(\ell)}\right\|_{H\to H}
  +\left\|D^{(\ell)}\right\|_{H\to H}\,\left\|\Delta W^{(\ell)}\right\|_{H\to H}\\
&\le M_\sigma R\,B_W + L_\sigma,
\end{align*}
where the two terms come from differentiating $D^{(\ell)}$ and $W^{(\ell)}$, respectively. For
$m>\ell$, only the $D^{(m)}$-factor depends on $W^{(\ell)}$, through
\begin{align*}
\partial_{W^{(\ell)}}z^{(m)}[\Delta W^{(\ell)}]
= W^{(m)}G^{(m-1)}\cdots G^{(\ell+1)}
D^{(\ell)}\Delta W^{(\ell)}a^{(\ell-1)},
\end{align*}
with the intermediate product interpreted as the identity when $m=\ell+1$,
so that
\begin{align*}
\left\|\partial_{W^{(\ell)}}G^{(m)}[\Delta W^{(\ell)}]\right\|_{H\to H}
&\le M_\sigma\,\left\|\partial_{W^{(\ell)}}z^{(m)}[\Delta W^{(\ell)}]\right\|_H\,\left\|W^{(m)}\right\|_{H\to H}\\
&\le M_\sigma B_W (L_\sigma B_W)^{m-\ell} R.
\end{align*}
Setting
\begin{align*}
\Gamma := \max\bigl\{L_\sigma B_W,\ L_\sigma+M_\sigma R B_W,\ M_\sigma B_W (L_\sigma B_W)^{N-1} R\bigr\},
\end{align*}
each summand above is a product of $N$ factors of norm at most $\Gamma$.
The same bounds apply to unit bias directions, replacing
$\Delta W^{(\ell)}a^{(\ell-1)}$ by $\Delta b^{(\ell)}$ and omitting the direct
weight-derivative term, since $R\ge1$.
Summing the at most $N$ summands and accounting for the $N$ weight and $N$ bias blocks gives
\begin{align*}
\left\lVert \partial_y\partial_{W_k}f_{W_k}(y)\right\rVert_{H\times P\to H}
\le 2N^2\Gamma^{N} =: M_{Wf};
\end{align*}
the mean value theorem on the hidden-state ball yields equation~\ref{eq:bound4}.

\emph{(iii) Second-order $W$-regularity.} The map $\partial_{W_k}f_{W_k}(y)$ is the sum over
$\ell=1,\ldots,N$ of the two blocks displayed in \emph{(ii)}. Differentiating each block once more
with respect to $W_k$ applies the product rule a second time, so every resulting term is a product
of factors, each of which is one of $\sigma'(z^{(m)})$, $\sigma''(z^{(m)})$, a weight matrix
$W^{(m)}$, an activation $a^{(m)}$, the input $y$, or a direction $\Delta U_k,\Delta V_k$.
Take $\left\|\Delta U_k\right\|_P,\left\|\Delta V_k\right\|_P\le1$.
By the choice of $M_\sigma$, the second-order activation terms satisfy
\begin{align*}
\left\|\sigma''(z)\odot u\odot v\right\|_H
\le d^{1/p}\sup_{t\in\mathbb{R}}|\sigma''(t)|\,\left\|u\right\|_H\,\left\|v\right\|_H
\le M_\sigma\,\left\|u\right\|_H\,\left\|v\right\|_H,
\end{align*}
where $\odot$ denotes componentwise multiplication.
On the ball $\{\left\|y\right\|_H\le C_y\}$ every such factor is bounded,
and the total number of terms is bounded by a constant depending only on $N$. Hence
\begin{align*}
\left\lVert \partial^2_{W_k}f_{W_k}(y)\right\rVert_{P\times P\to H} \le M_{WW}
\qquad\text{on } \{\left\|y\right\|_H\le C_y\},
\end{align*}
and the mean value theorem over $\Omega$ gives equation~\ref{eq:bound5}. All constants depend only on
$N,L_\sigma,M_\sigma,B_W,B_b,C_y$.

\emph{(iv) The initial bound.} Since $\left\|y_0\right\|_H=\left\|x\right\|_H\le C_x$, rerunning the
bounded-activation induction on the ball $\{\left\|y\right\|_H\le C_x\}$ (in place of $C_y$) gives
\begin{align*}
\left\|f_{W_k}(y_0)\right\|_H = \left\|a^{(N)}\right\|_H \le R_x =: C_f,
\qquad R_x = R(N,L_\sigma,B_W,B_b,C_x),
\end{align*}
which does not depend on $C_y$. This completes the verification of \cref{as2} in the localized
sense of \cref{rem:loc}.

